public static Node Union(Node a1, Node b1)
{
    Node a = a1.Clone();
    Node b = b1.Clone();

    a.ClipTo(b);
    b.ClipTo(a);
    b.Invert();
    b.ClipTo(a);
    b.Invert();

    a.Build(b.AllPolygons());

    Node ret = new Node(a.AllPolygons());

    return ret;
}

public static Node Subtract(Node a1, Node b1)
{
    Node a = a1.Clone();
    Node b = b1.Clone();

    a.Invert();
    a.ClipTo(b);
    b.ClipTo(a);
    b.Invert();
    b.ClipTo(a);
    b.Invert();
    a.Build(b.AllPolygons());
    a.Invert();

    Node ret = new Node(a.AllPolygons());

    return ret;
}

public static Node Intersect(Node a1, Node b1)
{
    Node a = a1.Clone();
    Node b = b1.Clone();

    a.Invert();
    b.ClipTo(a);
    b.Invert();
    a.ClipTo(b);
    b.ClipTo(a);

    a.Build(b.AllPolygons());
    a.Invert();

    Node ret = new Node(a.AllPolygons());

    return ret;
}

