    public Node front;
    public Node back;

    public Plane plane;

    public Node()
    {
        front = null;
        back = null;
    }

    public Node(List<Polygon> list)
    {
        Build(list);
    }

    public Node(List<Polygon> list, Plane plane, Node front, Node back)
    {
        this.polygons = list;
        this.plane = plane;
        this.front = front;
        this.back = back;
    }

public void ClipTo(Node other)
{
    this.polygons = other.ClipPolygons(this.polygons);

    if (this.front != null)
    {
        this.front.ClipTo(other);
    }

    if (this.back != null)
    {
        this.back.ClipTo(other);
    }
}

// Convert solid space to empty space and empty space to solid space.
public void Invert()
{
    for (int i = 0; i < this.polygons.Count; i++)
        this.polygons[i].Flip();

    this.plane.Flip();

    if (this.front != null)
    {
        this.front.Invert();
    }

    if (this.back != null)
    {
        this.back.Invert();
    }

    Node tmp = this.front;
    this.front = this.back;
    this.back = tmp;
}

public void Build(List<Polygon> list)
